Dictionary VoxelTerrain::get_cairn_mesh_observation(Vector3i block_pos) const {
	Dictionary d;
	d["state"] = "missing";
	for (const char *key : {"loaded", "visible", "has_mesh", "mesh_id", "mesh_viewers", "collision_viewers", "queued_update", "desired_revision", "submitted_revision"}) d[key] = Variant();
	const VoxelMeshBlockVT *block = _mesh_map.get_block(block_pos);
	if (block == nullptr) return d;
	static const char *states[] = {"missing", "pending", "hidden", "visible", "confirmed_empty"};
	d["state"] = states[get_cairn_mesh_state(block_pos)];
	d["loaded"] = block->is_loaded;
	d["visible"] = block->is_visible();
	d["has_mesh"] = block->has_mesh();
	d["mesh_viewers"] = block->mesh_viewers.get();
	d["collision_viewers"] = block->collision_viewers.get();
	d["queued_update"] = block->is_in_update_list;
	if (block->cairn_revision != 0) d["desired_revision"] = int64_t(block->cairn_revision);
	if (block->cairn_submitted_revision != 0) d["submitted_revision"] = int64_t(block->cairn_submitted_revision);
	// Copy only the decimal object identity. No arrays/GPU readback and no Mesh
	// reference survives this synchronous main-thread call.
	const Ref<Mesh> mesh = block->get_mesh();
	if (mesh.is_valid()) d["mesh_id"] = String::num_uint64(uint64_t(mesh->get_instance_id()));
	return d;
}

